package main

import (
	"fmt"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
	"github.com/caddyserver/caddy/v2/modules/caddyhttp"
)

func main() {
	for _, input := range []string{
		"client_ip 1.2.3.4\nclient_ip 5.6.7.8 9.10.11.12\nclient_ip 1.2.3.4",
		"remote_ip 1.2.3.4\nremote_ip 5.6.7.8 9.10.11.12\nremote_ip 1.2.3.4",
	} {
		if input[0] == 'c' {
			m := caddyhttp.MatchClientIP{}
			err := m.UnmarshalCaddyfile(caddyfile.NewTestDispenser(input))
			fmt.Printf("client err=%v ranges=%v\n", err, m.Ranges)
		} else {
			m := caddyhttp.MatchRemoteIP{}
			err := m.UnmarshalCaddyfile(caddyfile.NewTestDispenser(input))
			fmt.Printf("remote err=%v ranges=%v\n", err, m.Ranges)
		}
	}
}

package main

import (
	"fmt"

	"github.com/caddyserver/caddy/v2/caddyconfig"
	_ "github.com/caddyserver/caddy/v2/caddyconfig/httpcaddyfile"
	_ "github.com/caddyserver/caddy/v2/modules/standard"
)

func main() {
	input := []byte(`:80 {
	@webhook {
		path /webhook
		not {
			client_ip 51.138.37.238 20.54.89.16
			client_ip 20.50.240.57 40.74.20.78
			client_ip 1.2.3.4
		}
	}
	handle @webhook {
		abort
	}
}
`)
	adapter := caddyconfig.GetAdapter("caddyfile")
	out, warnings, err := adapter.Adapt(input, nil)
	fmt.Printf("err=%v warnings=%v\n%s\n", err, warnings, out)
}
